  {
    id: 'sana',
    name: 'Sana Iqbal',
    email: 'sana@example.com',
    title: 'Backend engineer',
    role: 'member',
    presence: 'tracking',
    isYou: false,
  },
  {
    id: 'tomas',
    name: 'Tomás Rivera',
    email: 'tomas@example.com',
    title: 'QA engineer',
    role: 'member',
    presence: 'away',
    isYou: false,
  },
  {
    id: 'mei',
    name: 'Mei Lin',
    email: 'mei@example.com',
    title: 'Content designer',
    role: 'viewer',
    presence: 'offline',
    isYou: false,
  },
  {
    id: 'jonas',
    name: 'Jonas Weber',
    email: 'jonas@example.com',
    title: 'Data analyst',
    role: 'member',
    presence: 'online',
    isYou: false,
  },
